INSERT OR IGNORE INTO settings(key,value) VALUES('seo_description','Coffee Time is a board game for 2 to 6 players, ages 8 and up. Team up as the coffee heroes or play King Tea and race the clocks across five worlds. Made in Davis, California.');
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_lede','Home: under the title','text','home','A board game for the whole table. Team up as the coffee heroes, or play King Tea and his crumpet army, and race the clocks across five worlds before it strikes Tea Time forever.',0);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_sides_title','Home: heroes vs villains heading','line','home','Pick a side.',1);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_heroes','Home: the heroes','text','home','Up to four players work together as Cup Joe, Thermos, Little Miss Hot Shot and Donette. Share heat, trade cards, fight off crumpets and reach the Activation Chamber in time to challenge the king.',2);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_villains','Home: the villains','text','home','King Tea rolls the clocks forward and sends his Royal Guards after the heroes. Roamer climbs out of the grave every round to attack and steal. They only need sixty hours.',3);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_box_title','Home: in the box heading','line','home','What''s in the box',4);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_box','Home: in the box list','text','home','- 20 by 20 inch game board with moveable clock hands
- 59 Journey Cards (18 kinds, plus 2 King''s Cards and a Card Protector)
- 19 Roamer Cards
- 6 Player Cards and 6 player pieces
- 4 dice: d4, d8, d10 and d12
- Instructions and the Coffee Time story
- First-edition patch with 4 bonus cards',5);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_game_title','Home: video game heading','line','home','Now you can walk around in it.',6);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_game','Home: video game text','text','home','Coffee Time Adventures is a 3D video game set in the Five Worlds, built in Davis by a game club of students and volunteers. Play as Little Miss Hot Shot and sneak through Crumpet World Cemetery in the free Windows demo.',7);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_davis_title','Home: made in Davis heading','line','home','Made in Davis. Played everywhere.',8);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('home_davis','Home: made in Davis text','text','home','Coffee Time took five years of design and playtesting by friends in Davis, California. Since launching in 2023 it has been to San Diego Comic-Con twice, onto KDVS radio, and all the way to a coffee farm in Curití, Colombia.

**5% of every game sold goes to Purple Tree Café**, a Davis nonprofit that employs people with disabilities to bake and sell vegan treats.',9);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('order_intro','Order: intro','text','order','Fill this in and we will email you within a couple of days to confirm shipping and arrange payment. Nothing is charged on this website.',10);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('order_after','Order: thank-you message','text','order','Got it. We will email you shortly to confirm the total with shipping and how to pay. Thanks for supporting a homegrown game.',11);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('order_local','Order: pickup note','text','order','Live near Davis? Say so in the notes and we can arrange a local pickup.',12);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('worlds_intro','Five Worlds: intro','text','worlds','King Tea has broken into the Realm of Time. His clocks tick from Coffee World to Tea World, and if they reach Tea Time in the last one, coffee is gone for good. Here is where the journey goes.',13);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('worlds_story','Five Worlds: illustrated story intro','text','worlds','The original illustrated story that comes in the box, all eight pages.',14);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('game_intro','Video game: intro','text','video-game','The board game is growing into a 3D open-world adventure, made in Unreal Engine by a Davis game club. You play Little Miss Hot Shot, crossing the Five Worlds to stop King Tea.',15);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('game_demo','Video game: about the demo','text','video-game','The free Windows demo (about 792 MB, name your own price) is one slice of the bigger game: Crumpet World Cemetery, a glowing graveyard patrolled by crumpet guards.

- Sneak past guards without being spotted
- Find coffee beans, mugs and hidden treasure
- Look closely for a secret jetpack
- Press Q to try the experimental helipads',16);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('game_club','Video game: the club','text','video-game','The project is led by club instructor and sound designer Nick Domke, with Milly Wedra as the voice of Little Miss Hot Shot. Students pitch in on modeling, sound, story, interface design and gameplay. No experience needed, just curiosity.',17);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('music_intro','Music: intro','text','music','Every world has a theme. These tracks were made for Coffee Time with eNuminous and Archimedes, and they are becoming the soundtrack of the video game.',18);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('play_intro','How to play: intro','text','how-to-play','Everything you need to run a game, in the order you will need it. New players start at lesson 1. Mid-game ruling? Jump to the chapter.',19);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('community_intro','Community: intro','text','community','Coffee Time was made by friends, and it keeps growing the same way: artists, musicians, playtesters, a game club and a few hundred families who play it.',20);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('community_creators','Community: the creators','text','community','Aaron Wedra and Stevie Price designed the game. Landon Christensen and Sam Lundholm contributed art, Milly Judd edited, and Matthew Wright wrote the music.

Aaron sums it up: dive into the characters'' worlds and help Cup Joe and his friends stop King Tea from making it Tea Time forever. Or sound the trumpets and join the crumpets.',21);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('community_charity','Community: Purple Tree Café','text','community','5% of every Coffee Time purchase goes to Purple Tree Café. The Davis nonprofit employs people with disabilities to make and sell vegan baked goods, and brings people with and without disabilities together through music and art.',22);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('community_hmp','Community: HMP Bikes','text','community','HMP Bikes, at 440 F Street in downtown Davis, builds sustainable, affordable last-mile transportation. They sponsor the game, and inspired one of its happiest pieces of character art.',23);
INSERT OR IGNORE INTO blocks(key,label,kind,page,value,sort) VALUES('contact_intro','Contact: intro','text','contact','Rules question, school or nonprofit event, press, or you just want to say hi. Write to us here and it reaches the Coffee Time team.',24);
INSERT OR IGNORE INTO worlds(slug,name,tagline,body,who,color,image,sort) VALUES('coffee-world','Coffee World','Where every hour is Coffee Time.','Home of Cup Joe, Thermos and Little Miss Hot Shot. A spirited land where friends gather, energy flows and the coffee is always on. It is also where King Tea''s clocks start ticking.','Cup Joe, Thermos, Little Miss Hot Shot','#8a4b23','/img/cup-joe.webp',1);
INSERT OR IGNORE INTO worlds(slug,name,tagline,body,who,color,image,sort) VALUES('donut-world','Donut World','Chocolate rivers and seas of sprinkles.','Donette''s magical home: chocolate rivers, pink-frosting mountaintops, seas of sprinkles, and the famously hungry pup-pups. Feed them before they feed on you.','Donette, the pup-pups','#d93a8c','/img/donette.webp',2);
INSERT OR IGNORE INTO worlds(slug,name,tagline,body,who,color,image,sort) VALUES('warp-world','Warp World','Portals that run on rhythm.','A frontier of beats, sounds, rhythms and tempos, and the mysterious border between the kingdoms of coffee and tea. Team Warp cards jump you across the board from here.','The Activation Chamber','#6b3fc4','/img/card-team-warp.webp',3);
INSERT OR IGNORE INTO worlds(slug,name,tagline,body,who,color,image,sort) VALUES('crumpet-world','Crumpet World','A graveyard under the full moon.','King Tea''s proud moonlit kingdom, where loyal Royal Guards and endless crumpet forces gather below the castle walls. Under the full moon, Roamer is at his strongest here.','Roamer, the Royal Guards, the crumpets','#3c7a5a','/img/roamer.webp',4);
INSERT OR IGNORE INTO worlds(slug,name,tagline,body,who,color,image,sort) VALUES('tea-world','Tea World','The last stop before Tea Time.','A fragile, elegant kingdom of parades, feasts and moon-garden ceremonies. If King Tea''s clock reaches twelve here, coffee is vanquished forever and tea and crumpets rule the Five Worlds.','King Tea, the Duchess','#2c6fc0','/img/king-tea.webp',5);
INSERT OR IGNORE INTO characters(name,side,power,image,sort) VALUES('Cup Joe','hero','The hero at the heart of Coffee World. Help Cup Joe and his friends stop King Tea.','/img/cup-joe.webp',0);
INSERT OR IGNORE INTO characters(name,side,power,image,sort) VALUES('Thermos','hero','Starts the game holding the Card Protector, and can keep it or share it with the team.','/img/thermos.webp',1);
INSERT OR IGNORE INTO characters(name,side,power,image,sort) VALUES('Little Miss Hot Shot','hero','Fast enough to shrug off every Duchess Enchantment. Also the star of the video game.','/img/little-miss-hot-shot.webp',2);
INSERT OR IGNORE INTO characters(name,side,power,image,sort) VALUES('Donette','hero','Has no temperature gauge, so she can never freeze. On the Activation Button she powers up the whole board.','/img/donette.webp',3);
INSERT OR IGNORE INTO characters(name,side,power,image,sort) VALUES('King Tea','villain','Rolls the clocks forward through the Five Worlds. Sixty hours and it is Tea Time forever.','/img/king-tea.webp',4);
INSERT OR IGNORE INTO characters(name,side,power,image,sort) VALUES('Roamer','villain','Already undead, so he never dies. Rises every round to attack heroes and rob their cards.','/img/roamer.webp',5);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Zacharia O.','Player','A living story, a clear adventure, meaningful cooperation and just the right balance of tension and conflict.',1,0);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Nicole Garcia','Playtester','The graphics are wonderful and the storyline is great. Overall it is really fun. It will be the next big thing!',1,1);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Daphne','San Diego Comic-Con','It reminds me a lot of Mario Party.',1,2);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Christian Garcia','Playtester','Coffee Time is the Dark Souls of board games. It combines video game elements with traditional board game mechanics.',0,3);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Matt R.','San Diego Comic-Con','It reminds me of having coffee time with my grandma.',0,4);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Ashley R.','San Diego Comic-Con','I like to play as King Tea, because I can''t let Coffee win!',0,5);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Lauren Z.','San Diego Comic-Con','A cute, fast-paced casual game, and the clocks created a unique gameplay experience.',0,6);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Avery Armstrong Stockert','Playtester','Coffee Time is dope. If there''s ever an opportunity to be an investor, count me in.',0,7);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Violet Price','Playtester','This game is awesome, and it has been so cool to watch Aaron and Stevie perfect the game over the years!',0,8);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Cynthia C.','Playtester','I won as King Tea and it felt really good!',0,9);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Johnny','Playtester','An intricate and awesome gaming experience!',0,10);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Alec','Playtester','It''s the perfect game for a night in with friends or family.',0,11);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Christopher McCreary','Playtester','This game marked the beginning of our friendship and will keep bringing people together for years to come.',0,12);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Dewey Bandy','Playtester','A great game for social occasions. It''s engaging even for a new player.',0,13);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Ben Klein','Playtester','With six different playable characters, each game requires different tactics and offers different rewards.',0,14);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Landon Christensen','King Tea designer','King Tea is the ultimate villain. Anytime is the right time to play Coffee Time.',0,15);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Sam Lundholm','Abstract art designer','I just had fun creating the art. Now you can have fun playing the game.',0,16);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Milly Judd','Editor','We hope you''ll enjoy our clever, creative and captivating game. It''s a latte fun!',0,17);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Phoenix Newton','Bought the game','I would like to see Coffee Time go global one day.',0,18);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Colin Walsh','Bought the game','No doubt about it. Coffee Time is the hot new game.',0,19);
INSERT OR IGNORE INTO reviews(name,role,quote,featured,sort) VALUES('Purple Tree Café','Game beneficiary','Thanks for including us on this journey, and for donating a portion of proceeds to Purple Tree Café.',0,20);
INSERT OR IGNORE INTO news(date_label,title,body,image,image_alt,url,link_label,sort) VALUES('2026','Coffee Time becomes a world you can walk into','The board game is growing into a 3D video game, Coffee Time Adventures, built in Unreal Engine by a Davis game club led by Nick Domke, with Milly Wedra voicing Little Miss Hot Shot. A free Windows demo is out now while new worlds, characters and music take shape.','/img/game/adventures-5.webp','Little Miss Hot Shot jumping between platforms in Coffee Time Adventures','https://dvgameclub.itch.io/coffee-time-adventures','Play the free demo',0);
INSERT OR IGNORE INTO news(date_label,title,body,image,image_alt,url,link_label,sort) VALUES('2025','Back at San Diego Comic-Con','Coffee Time returned to Comic-Con alongside big-name creators and first-time game makers. By then more than 600 copies were being played by families, fans and nonprofits around the country and overseas.','/img/comic-con-2025.webp','Collage of players at the Coffee Time table at San Diego Comic-Con 2025','','',1);
INSERT OR IGNORE INTO news(date_label,title,body,image,image_alt,url,link_label,sort) VALUES('November 2024','Invited to San Diego Comic-Con','Day one started slow and turned into nonstop battles between coffee heroes and tea villains. Day two brought dozens of new players of every age. On day three, people came looking for the table after finding Coffee Time in the program.','/img/comic-con-players.webp','Players around the Coffee Time board at Comic-Con','','',2);
INSERT OR IGNORE INTO news(date_label,title,body,image,image_alt,url,link_label,sort) VALUES('June 2023','On the air at KDVS 90.3 FM','Radio host Emcee Escher featured Coffee Time on How Did We Get Here?, talking through the journey from first idea to finished game.','/img/kdvs-radio.webp','Artwork for the Coffee Time radio feature on KDVS','','',3);
INSERT OR IGNORE INTO news(date_label,title,body,image,image_alt,url,link_label,sort) VALUES('March 2023','The first 100 games','We sold our first 100 games thanks to you. If we can make it in our hometown of Davis, we can make it anywhere. One of those first copies traveled all the way to a coffee farm in Curití, Colombia.','/img/first-100-games.webp','The Coffee Time team celebrating 100 games sold','','',4);
INSERT OR IGNORE INTO news(date_label,title,body,image,image_alt,url,link_label,sort) VALUES('March 2023','A playthrough with Davis Cards & Games','Creators Aaron and Milly joined Melissa and Jake from Davis Cards & Games for a first-time playthrough streamed on Twitch.','','','','',5);
INSERT OR IGNORE INTO news(date_label,title,body,image,image_alt,url,link_label,sort) VALUES('March 2023','Launch party on Good Day Sacramento','Reporter Julissa Ortiz interviewed the creators and invited local viewers to the official launch party.','','','','',6);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Get started','1','Open the box and set up','Lay out the board, cards and player pieces. Choose who plays the Coffee Time heroes, who plays King Tea and who plays Roamer. Match each hero with their Player Card and their movement die.',0);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Move and battle','2A','Moving a hero','Roll the die shown on your Player Card and add any extra movement from your hero ability or the current world. Always draw a Journey Card after you move.',1);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Move and battle','2B','Team Path crossroads','Landing on a Team Path Crossroads puts you on the Team Path straight away. On your next turn, take the purple Team Path or keep going on your original route.',2);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Move and battle','3','Battling a common enemy','- Win: put the enemy card on the bottom of the Journey Deck.
- Lose: lose one health and discard the enemy.
- Tie: both sides roll again.',3);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Move and battle','4','Out of health','Each lost battle against a common enemy costs one health. At zero, go back to Start and refill your health. Temperature does not refill.',4);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Move and battle','5','Team Path powers','Heroes on a round Team Path space or in the Activation Chamber share their Team Path powers. Read each active power out loud. If Donette is on the Activation Button, the whole board shares Team Path powers.',5);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Move and battle','6','The Activation Chamber','Only one hero can stand on the Activation Button. A hero entering an empty Chamber takes it right away, and an incoming hero can push another one off. A hero who starts a turn in the Chamber can also take over. If the button holder is defeated, the other heroes agree on a replacement.',6);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','7','Temperature, freezing and sharing heat','Ice lowers temperature by two. At zero you are frozen: you cannot move, draw, battle or use cards except Fire, and Roamer and the Guards cannot attack you. A frozen button holder keeps the activation power. At the start of a turn, coffee heroes can pass heat one for one. Donette has no temperature gauge and cannot freeze.',7);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','8','Card Protector','Thermos starts with the Card Protector and can keep it or share it. Lay it sideways across one item card. That item is safe from Roamer''s grave-robbing and from the Duchess.',8);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','9','Earth','Play Earth once to dodge a Roamer attack, or to stop Roamer stealing an item after a successful grave-robbing roll.',9);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','10','Health','Use Health any time on your turn to refill before you hit zero, or after a defeat to recover instead of going back to Start.',10);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','11','Honey Bee Queen','Dotty sends your hero straight to the Activation Chamber. Use it now or save it for later, then draw another Journey Card when you arrive.',11);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','12','Sprinkles','Turn Sprinkles into any usable or shareable card. Once you name it, that is what it stays. Name it right away or wait until any player''s turn.',12);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','13','Wind Feather','A gust that lets heroes trade cards with no limit. The Card Protector can also change hands and cover a new item. One use.',13);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','14','Sleepy Time Tea','Turn the clocks back six hours, or gamble on a d12 roll for the number of hours. King Tea loses the hours he gained most recently. One use.',14);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','15','Team Warp','Jump to the next Team Path crossroads. If you have passed both, go to the Activation Chamber. Already on the Team Path? Take an extra roll. Draw after every move.',15);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','16','Sugar Cube','Roll again right after drawing, or save it and play it at the end of a later turn to take a second turn.',16);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Cards and powers','17','Duchess Enchantments','The Duchess can send you to Start, make you discard unprotected items, freeze you, or summon Full Moon Roamer. Little Miss Hot Shot is fast enough to discard every Duchess Enchantment with no effect.',17);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Roamer','18','Playing Roamer','Draw a Roamer Card to spawn, then roll d4 plus 2 to move along any hero path. Attack one hero in reach with a d12. At the end of the turn, grave-rob any hero by winning a battle; protected items are safe. In Crumpet World, Full Moon Roamer rolls two d12s and adds them.

On the Activation Button, Roamer steals one unprotected item from every player without a battle. The Trumpet can once spawn Roamer anywhere with Full Moon power, or once set up a full-round defense that stops attacks on the Realm of Time.',18);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('King Tea','19','Playing King Tea','Choose to move or battle first. To move, roll the d12 and advance the World Clocks from left to right. Reaching 12 moves King Tea into the next world. Royal Guards can attack any hero with a d12 and drain all their health on a win; a defeated Guard is out for the game.

Once per game, Overtime doubles the hours you just rolled. In Tea World, Ice Storm can lower every hero''s temperature by one at the end of each King Tea turn.',19);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Win the game','20A','King Tea wins','If King Tea reaches 12, Tea Time, in Tea World, coffee is vanquished, the Five Worlds fall out of balance, and tea and crumpets reign supreme.',20);
INSERT OR IGNORE INTO lessons(chapter,num,title,body,sort) VALUES('Win the game','20B','The heroes win','Defeat every Royal Guard, reach the Activation Chamber, and wait for the start of your next turn to challenge King Tea. Both roll a d12. If the hero loses, back to Start. If King Tea loses, the Five Worlds are saved.',21);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('How does a full turn go?','**Heroes:** decide whether to share one item card and/or heat. Use any item cards you want, announcing each one. Move as your Player Card says (the Activation Chamber has its own rules). Then draw a Journey Card: battle enemies, use or keep items, and follow any Duchess Enchantment.

**Roamer:** choose whether to use one Trumpet function, move as the Player Card says, attack a hero in reach if you like, try to grave-rob, then go back to the grave. Roamer is already undead and never dies. He plays every round, can grave-rob even after losing a battle, and discards stolen cards instead of using them.

**King Tea:** choose to move or attack first. When moving, roll, advance the clocks, and decide right then whether to use Overtime. When attacking, use the Royal Guard battle rules. In Tea World, Ice Storm can be used at the end of the turn.',0);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('What if Roamer goes first?','If Roamer wins the opening roll and plays before any hero has moved, he can use that first turn to try to grave-rob Thermos''s Card Protector. It is the only moment in the game when the Card Protector itself can be taken.',1);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('How does King Tea move through the Five Worlds?','Roll the d12 and move the clock hands that many hours, starting in Coffee World and continuing through Donut, Warp, Crumpet and Tea World.

Example: at 11:00 in Coffee World, a roll of 3 reaches 12:00 there and carries on to 2:00 in Donut World. The King Tea piece can stay on its Realm of Time home space.

King Tea needs 60 hours in total to win, plus any hours the heroes turn back with Sleepy Time Tea.',2);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('When can a hero share heat or item cards?','At the start of that hero''s turn, before rolling to move. Heat moves one step at a time, and each step given is taken off the hero who shares it.',3);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('If I land on a Team Path Crossroads, am I on the Team Path?','Yes. Your Team Path power switches on right away. Every round space and the Activation Chamber count as Team Path spaces. On your next turn, take the purple Team Path or stay on your original route and give up shared Team Path powers.',4);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('What does the 0 on the ten-sided die mean?','It counts as 10.',5);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('Can a hero be attacked on their Start space?','Technically yes, but their health is full there, so the attack does nothing.',6);
INSERT OR IGNORE INTO faqs(question,answer,sort) VALUES('Can Earth stop Roamer''s Activation Power?','No. Roamer''s Activation Power steals one item of his choice from every player. That is not a normal grave-robbing roll, so Earth cannot stop it. The Card Protector still keeps its item safe.',7);
